// src/pages/admin/Repayments.js
import React, { useState, useEffect } from 'react';
import { loansAPI, repaymentsAPI } from '../../services/api';
import { Wallet, ChevronDown, Plus } from 'lucide-react';
import RepaymentModal from '../../components/ui/RepaymentModal';

const fmtMoney = (n) => new Intl.NumberFormat('en-US').format(n || 0) + ' FCFA';
const fmtDate = (d) => d ? new Date(d).toLocaleDateString('en-US') : '—';

export default function Repayments() {
  const [loans, setLoans] = useState([]);
  const [selectedLoan, setSelectedLoan] = useState('');
  const [repayments, setRepayments] = useState([]);
  const [pending, setPending] = useState([]);
  const [loading, setLoading] = useState(false);
  const [showPayModal, setShowPayModal] = useState(false);

  const loadLoans = () => {
    loansAPI.getAll().then(r => setLoans(r.data.data)).catch(() => {});
  };

  useEffect(() => {
    loadLoans();
  }, []);

  const handleSelect = async (loanId) => {
    setSelectedLoan(loanId);
    if (!loanId) {
      setRepayments([]);
      setPending([]);
      return;
    }
    setLoading(true);
    try {
      const [r, p] = await Promise.all([
        repaymentsAPI.getByLoan(loanId),
        repaymentsAPI.getPending(loanId),
      ]);
      setRepayments(r.data.data);
      setPending(p.data.data);
    } catch {}
    setLoading(false);
  };

  const loan = loans.find(l => l._id === selectedLoan);
  const totalPaid = repayments.reduce((s, r) => s + r.amount, 0);

  return (
    <div className="fade-in">
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 24 }}>
        <div>
          <h1 style={{ fontSize: 22, marginBottom: 4 }}>Repayments</h1>
          <p style={{ color: 'var(--gray-500)', fontSize: 13 }}>Track payments by loan</p>
        </div>
        <button className="btn btn-primary" onClick={() => setShowPayModal(true)}>
          <Plus size={15} /> New Payment
        </button>
      </div>

      {/* Loan selector */}
      <div className="card" style={{ padding: '16px 20px', marginBottom: 20 }}>
        <label style={{ display: 'block', fontSize: 12, fontWeight: 600, color: 'var(--gray-500)', textTransform: 'uppercase', letterSpacing: 0.5, marginBottom: 8 }}>
          Select a loan to view history
        </label>
        <select className="form-control" style={{ maxWidth: 400 }} value={selectedLoan} onChange={e => handleSelect(e.target.value)}>
          <option value="">— Choose a loan —</option>
          {loans.map(l => (
            <option key={l._id} value={l._id}>
              {l.clientId?.name} — {fmtMoney(l.amount)} — {l.status}
            </option>
          ))}
        </select>
      </div>

      {selectedLoan && loan && !loading && (
        <>
          {/* Summary */}
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4,1fr)', gap: 14, marginBottom: 20 }}>
            {[
              { label: 'Total Loan', value: fmtMoney(loan.totalRepayable) },
              { label: 'Total Paid', value: fmtMoney(totalPaid), success: true },
              { label: 'Remaining', value: fmtMoney(Math.max(0, (loan.totalRepayable || 0) - totalPaid)), danger: (loan.totalRepayable - totalPaid) > 0 },
              { label: 'Payments Made', value: repayments.length },
            ].map(({ label, value, success, danger }) => (
              <div key={label} className="stat-card" style={{ padding: 16 }}>
                <div style={{ fontSize: 11, color: 'var(--gray-500)', fontWeight: 600, textTransform: 'uppercase', marginBottom: 6 }}>{label}</div>
                <div style={{ fontSize: 18, fontWeight: 700, color: success ? 'var(--success)' : danger ? 'var(--danger)' : 'var(--gray-900)' }}>{value}</div>
              </div>
            ))}
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 20 }}>
            {/* Pending */}
            <div className="card">
              <div style={{ padding: '14px 18px', borderBottom: '1px solid var(--gray-100)' }}>
                <h3 style={{ fontSize: 14 }}>Remaining installments ({pending.length})</h3>
              </div>
              <div style={{ maxHeight: 400, overflowY: 'auto' }}>
                {pending.length === 0 ? (
                  <div className="empty-state"><Wallet size={32} /><p>All installments are paid</p></div>
                ) : (
                  <table>
                    <thead><tr><th>Month</th><th>Amount</th><th>Date</th><th>Status</th></tr></thead>
                    <tbody>
                      {pending.map(p => (
                        <tr key={p._id}>
                          <td>Month {p.monthNumber}</td>
                          <td style={{ fontWeight: 600 }}>{fmtMoney(p.amountDue)}</td>
                          <td>{fmtDate(p.dueDate)}</td>
                          <td>
                            <span className={`badge ${p.status === 'OVERDUE' ? 'badge-danger' : 'badge-warning'}`}>
                              {p.status === 'OVERDUE' ? 'Overdue' : 'Pending'}
                            </span>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                )}
              </div>
            </div>

            {/* History */}
            <div className="card">
              <div style={{ padding: '14px 18px', borderBottom: '1px solid var(--gray-100)' }}>
                <h3 style={{ fontSize: 14 }}>Payment History ({repayments.length})</h3>
              </div>
              <div style={{ maxHeight: 400, overflowY: 'auto' }}>
                {repayments.length === 0 ? (
                  <div className="empty-state"><Wallet size={32} /><p>No payments recorded</p></div>
                ) : (
                  <table>
                    <thead><tr><th>Amount</th><th>Date</th><th>Note</th></tr></thead>
                    <tbody>
                      {repayments.map(r => (
                        <tr key={r._id}>
                          <td style={{ fontWeight: 600, color: 'var(--success)' }}>{fmtMoney(r.amount)}</td>
                          <td>{fmtDate(r.paidAt)}</td>
                          <td style={{ color: 'var(--gray-500)' }}>{r.note || '—'}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                )}
              </div>
            </div>
          </div>
        </>
      )}

      {!selectedLoan && (
        <div className="card" style={{ padding: 48, textAlign: 'center' }}>
          <Wallet size={40} style={{ opacity: 0.3, marginBottom: 12 }} />
          <p style={{ color: 'var(--gray-400)' }}>Select a loan to view repayments</p>
        </div>
      )}

      {showPayModal && (
        <RepaymentModal 
          onClose={() => setShowPayModal(false)} 
          onSave={() => {
            setShowPayModal(false);
            if (selectedLoan) handleSelect(selectedLoan);
            loadLoans();
          }}
        />
      )}
    </div>
  );
}
